import { expect, expectStatus, test } from "../../fixtures";

test("Fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  expect(vendor.status, "vendor starts as a draft").toBe("draft");
  const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt", "member");

  // Act: extraction runs in the background, so wait for the document to finish processing.
  await expect
    .poll(
      async () => {
        const response = await member.get(`/api/documents/${document.id}`);
        return (await expectStatus<{ status: string }>(response, 200)).status;
      },
      { message: "insurance certificate finishes processing", timeout: 30_000 },
    )
    .toBe("extracted");

  // Assert: read the stored extraction, not just the document status.
  const response = await member.get(`/api/documents/${document.id}/extraction`);
  const extraction = await expectStatus<{ fields: Record<string, { value: string | null; confidence: number }> }>(
    response,
    200,
  );
  const expiry = extraction.fields.expiry_date;
  expect(expiry, "expiry_date field is present").toBeDefined();
  expect(expiry.value, "unparseable expiry date is stored as null").toBeNull();
  expect(expiry.confidence, "unparseable expiry date has confidence below 0.5").toBeLessThan(0.5);
});
